/** True when `v` is a catalog ref token (`__kind ∈ REF_SCOPE` + a string refName). */
export declare function isCatalogToken(v: unknown): boolean;
/** Reduce a catalog token to its canonical fields (dropping barrel bags etc.). */
export declare function slimToken(token: Record<string, unknown>): Record<string, unknown>;
/**
 * Deep-walk `node`, replacing every catalog token with its slim canonical form.
 * Non-token objects/arrays are recursed; scalars pass through. Tokens are not
 * recursed into (their bags are dropped wholesale).
 */
export declare function slimTokens(node: unknown): unknown;
